select coalesce(sum(r.points), 0) from student_point_record r
where r.user_id = #{userId} and r.create_time >= #{start} and r.create_time <= #{end}

	and r.biz_type in
	#{item}

select count(1) from student_point_record r
where r.user_id = #{userId}

	and r.biz_type in
	#{item}

select count(1) from student_point_record r

	and r.user_id = #{userId}
	and r.biz_type = #{bizType}

		and r.create_time >= concat(#{createTimeStart}, ' 00:00:00')


		and r.create_time <= concat(#{createTimeEnd}, ' 23:59:59')

select  from student_point_record r

	and r.user_id = #{userId}
	and r.biz_type = #{bizType}

		and r.create_time >= concat(#{createTimeStart}, ' 00:00:00')


		and r.create_time <= concat(#{createTimeEnd}, ' 23:59:59')


order by r.create_time desc, r.record_id desc
limit #{pageSize}

select count(1) from (
	select r.user_id as user_id, coalesce(sum(r.points), 0) as points
	from student_point_record r
	where r.create_time >= #{startTime} and r.points > 0
	group by r.user_id
) t
join student_point_account a on a.user_id = t.user_id
where t.points > #{points}
and a.stage = #{stage}
